ALTER TYPE "HandoffStatus" ADD VALUE IF NOT EXISTS 'DRAFT' BEFORE 'REQUESTED';
ALTER TYPE "HandoffStatus" ADD VALUE IF NOT EXISTS 'READY' BEFORE 'REQUESTED';
ALTER TYPE "HandoffStatus" ADD VALUE IF NOT EXISTS 'SENT' BEFORE 'REQUESTED';
CREATE TYPE "OnboardingTemplateStatus" AS ENUM ('DRAFT','PUBLISHED','INACTIVE');
CREATE TYPE "OnboardingCaseStatus" AS ENUM ('PENDING','IN_PROGRESS','BLOCKED','ACTIVATED','COMPLETED','CANCELLED');
CREATE TYPE "OnboardingMilestoneStatus" AS ENUM ('PENDING','IN_PROGRESS','BLOCKED','COMPLETED','SKIPPED');
CREATE TYPE "OnboardingEventType" AS ENUM ('HANDOFF_CREATED','HANDOFF_READY','HANDOFF_SENT','HANDOFF_ACCEPTED','HANDOFF_REJECTED','HANDOFF_CANCELLED','HANDOFF_REASSIGNED','ONBOARDING_STARTED','MILESTONE_COMPLETED','ONBOARDING_BLOCKED','ONBOARDING_UNBLOCKED','ONBOARDING_REASSIGNED','CUSTOMER_ACTIVATED','ONBOARDING_COMPLETED','ONBOARDING_CANCELLED','CORRECTION');
CREATE TYPE "OnboardingBackfillStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TYPE "OnboardingBackfillItemStatus" AS ENUM ('CREATED','SKIPPED','REVIEW_REQUIRED');

ALTER TABLE "customer_handoffs" ADD COLUMN "accountId" UUID, ADD COLUMN "contractId" UUID, ADD COLUMN "templateVersionId" UUID, ADD COLUMN "snapshot" JSONB, ADD COLUMN "revision" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "readyAt" TIMESTAMPTZ(3), ADD COLUMN "sentAt" TIMESTAMPTZ(3), ADD COLUMN "rejectedAt" TIMESTAMPTZ(3), ADD COLUMN "cancelledAt" TIMESTAMPTZ(3), ADD COLUMN "updatedByActorId" UUID, ADD COLUMN "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
