CREATE UNIQUE INDEX "customer_handoffs_one_active_origin" ON "customer_handoffs"("workspaceId","opportunityId") WHERE "opportunityId" IS NOT NULL AND "status" NOT IN ('COMPLETED','REJECTED','CANCELLED');

CREATE TABLE "onboarding_templates" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"name" TEXT NOT NULL,"status" "OnboardingTemplateStatus" NOT NULL DEFAULT 'DRAFT',"currentVersionId" UUID,"createdByActorId" UUID NOT NULL,"updatedByActorId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","name"));
CREATE INDEX "onboarding_templates_workspaceId_status_idx" ON "onboarding_templates"("workspaceId","status");
CREATE TABLE "onboarding_template_versions" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"templateId" UUID NOT NULL,"version" INTEGER NOT NULL,"status" "OnboardingTemplateStatus" NOT NULL DEFAULT 'DRAFT',"requiredOpportunityWon" BOOLEAN NOT NULL DEFAULT TRUE,"requiredAcceptedContract" BOOLEAN NOT NULL DEFAULT TRUE,"expectedDurationDays" INTEGER NOT NULL DEFAULT 14,"publishedAt" TIMESTAMPTZ(3),"createdByActorId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","templateId","version"),CHECK("expectedDurationDays">0));
CREATE INDEX "onboarding_template_versions_workspaceId_status_publishedAt_idx" ON "onboarding_template_versions"("workspaceId","status","publishedAt");
CREATE TABLE "onboarding_template_milestones" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"templateVersionId" UUID NOT NULL,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"position" INTEGER NOT NULL,"required" BOOLEAN NOT NULL DEFAULT TRUE,"expectedDurationHours" INTEGER NOT NULL,"dependsOnKey" TEXT,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),CONSTRAINT "onboarding_template_milestones_version_key_unique" UNIQUE("workspaceId","templateVersionId","key"),CONSTRAINT "onboarding_template_milestones_version_position_unique" UNIQUE("workspaceId","templateVersionId","position"),CHECK("position">0),CHECK("expectedDurationHours">0));
CREATE INDEX "onboarding_template_milestones_workspaceId_templateVersionId_required_idx" ON "onboarding_template_milestones"("workspaceId","templateVersionId","required");
CREATE TABLE "onboarding_cases" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"handoffId" UUID NOT NULL,"accountId" UUID NOT NULL,"opportunityId" UUID NOT NULL,"contractId" UUID NOT NULL,"templateVersionId" UUID NOT NULL,"ownerMemberId" UUID,"teamId" UUID,"queueId" UUID,"status" "OnboardingCaseStatus" NOT NULL DEFAULT 'PENDING',"blockingReasonCode" TEXT,"blockingComment" TEXT,"nextActionDescription" TEXT NOT NULL,"nextActionAt" TIMESTAMPTZ(3) NOT NULL,"revision" INTEGER NOT NULL DEFAULT 1,"startedAt" TIMESTAMPTZ(3),"targetAt" TIMESTAMPTZ(3) NOT NULL,"activatedAt" TIMESTAMPTZ(3),"completedAt" TIMESTAMPTZ(3),"cancelledAt" TIMESTAMPTZ(3),"createdByActorId" UUID NOT NULL,"updatedByActorId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","handoffId"),CHECK(("ownerMemberId" IS NOT NULL)::int + ("queueId" IS NOT NULL)::int = 1));
CREATE INDEX "onboarding_cases_workspaceId_ownerMemberId_status_targetAt_idx" ON "onboarding_cases"("workspaceId","ownerMemberId","status","targetAt");
CREATE INDEX "onboarding_cases_workspaceId_teamId_status_targetAt_idx" ON "onboarding_cases"("workspaceId","teamId","status","targetAt");
CREATE INDEX "onboarding_cases_workspaceId_status_nextActionAt_idx" ON "onboarding_cases"("workspaceId","status","nextActionAt");
CREATE TABLE "onboarding_milestones" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"onboardingCaseId" UUID NOT NULL,"templateMilestoneId" UUID NOT NULL,"key" TEXT NOT NULL,"nameSnapshot" TEXT NOT NULL,"position" INTEGER NOT NULL,"required" BOOLEAN NOT NULL,"dependsOnKey" TEXT,"ownerMemberId" UUID,"status" "OnboardingMilestoneStatus" NOT NULL DEFAULT 'PENDING',"dueAt" TIMESTAMPTZ(3) NOT NULL,"completedAt" TIMESTAMPTZ(3),"blockedAt" TIMESTAMPTZ(3),"evidence" TEXT,"revision" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","onboardingCaseId","key"));
CREATE INDEX "onboarding_milestones_workspaceId_onboardingCaseId_status_position_idx" ON "onboarding_milestones"("workspaceId","onboardingCaseId","status","position");
CREATE INDEX "onboarding_milestones_workspaceId_ownerMemberId_status_dueAt_idx" ON "onboarding_milestones"("workspaceId","ownerMemberId","status","dueAt");
CREATE TABLE "onboarding_events" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"handoffId" UUID,"onboardingCaseId" UUID,"milestoneId" UUID,"sequence" INTEGER NOT NULL,"type" "OnboardingEventType" NOT NULL,"previousStatus" TEXT,"newStatus" TEXT NOT NULL,"reason" TEXT NOT NULL,"safeMetadata" JSONB,"actorId" UUID NOT NULL,"idempotencyKey" TEXT NOT NULL,"occurredAt" TIMESTAMPTZ(3) NOT NULL,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","idempotencyKey"));
CREATE INDEX "onboarding_events_workspaceId_handoffId_sequence_idx" ON "onboarding_events"("workspaceId","handoffId","sequence");
CREATE INDEX "onboarding_events_workspaceId_onboardingCaseId_sequence_idx" ON "onboarding_events"("workspaceId","onboardingCaseId","sequence");
CREATE TABLE "onboarding_backfill_runs" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"runKey" TEXT NOT NULL,"status" "OnboardingBackfillStatus" NOT NULL DEFAULT 'RUNNING',"mode" TEXT NOT NULL,"candidateCount" INTEGER NOT NULL DEFAULT 0,"createdCount" INTEGER NOT NULL DEFAULT 0,"reviewCount" INTEGER NOT NULL DEFAULT 0,"skippedCount" INTEGER NOT NULL DEFAULT 0,"actorId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMPTZ(3),UNIQUE("workspaceId","id"),UNIQUE("workspaceId","runKey"));
CREATE TABLE "onboarding_backfill_items" ("id" UUID PRIMARY KEY,"workspaceId" UUID NOT NULL,"runId" UUID NOT NULL,"opportunityId" UUID NOT NULL,"status" "OnboardingBackfillItemStatus" NOT NULL,"reasonCode" TEXT NOT NULL,"handoffId" UUID,"safeEvidence" JSONB,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("workspaceId","id"),UNIQUE("workspaceId","runId","opportunityId"));
CREATE INDEX "onboarding_backfill_items_workspaceId_status_createdAt_idx" ON "onboarding_backfill_items"("workspaceId","status","createdAt");

