CREATE FUNCTION reject_onboarding_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'onboarding history is append-only'; END $$;
CREATE TRIGGER onboarding_events_append_only BEFORE UPDATE OR DELETE ON "onboarding_events" FOR EACH ROW EXECUTE FUNCTION reject_onboarding_history_mutation();
CREATE TRIGGER onboarding_backfill_items_append_only BEFORE UPDATE OR DELETE ON "onboarding_backfill_items" FOR EACH ROW EXECUTE FUNCTION reject_onboarding_history_mutation();
